      "cheatSheet": [
        {
          "label": "CTR, CPC, CPM & Conversion Rate",
          "formula": "CTR = (Clicks / Impressions) × 100 · CPC = Cost / Clicks · CR = (Conversions / Clicks) × 100",
          "note": "CPM = (Total Cost / Impressions) × 1,000."
        },
        {
          "label": "CPA, ROAS, ROI & CAC",
          "formula": "CPA = Ad Spend / Conversions · ROAS = Revenue / Ad Spend · ROI = ((Rev − Cost)/Cost) × 100",
          "note": "CAC = (Marketing + Sales Cost) / New Customers; healthy LTV : CAC ≥ 3 : 1."
        },
        {
          "label": "Google Ads Vickrey Auction",
          "formula": "Ad Rank = Max CPC Bid × Quality Score · Actual CPC = (Ad Rank Below / Your QS) + ₹0.01",
          "note": "Quality Score = Expected CTR + Ad Relevance + Landing Page Experience."
        },
        {
          "label": "RACE Strategic Framework",
          "formula": "Reach (Awareness) → Act (Interact) → Convert (Sale/Lead) → Engage (Retention/Loyalty)",
          "note": "Combine with POEM Media: Paid (Ads), Owned (Site/App), Earned (PR/Reviews)."
        },
        {
          "label": "Meta 3-Tier & Funnel Strategy",
          "formula": "Campaign (Objective) → Ad Set (Audience, Budget, Placement) → Ad (Creative/Copy)",
          "note": "TOFU (Cold/Lookalike) → MOFU (Retargeting) → BOFU (Dynamic Product/Cart Recovery)."
        },
        {
          "label": "Technical SEO Essentials",
          "formula": "Crawl → Index → Rank · LCP < 2.5s, INP < 200ms, CLS < 0.1 · JSON-LD Schema + robots.txt + XML Sitemap",
          "note": "On-Page (Title, H1, Alt, Canonical) vs Off-Page (High-DA Backlinks, Anchor Text)."
        }
      ]
